import { esc, options, empty, icon } from '../ui.js';
import { statuses } from '../data.js';
export default function records({state,ui}) {
 const all=state.records.filter(r=>(!ui.query||(r.name+r.email).includes(ui.query))&&(!ui.status||r.status===ui.status)&&(!ui.owner||r.owner===ui.owner)&&(!ui.email||r.email.includes(ui.email))&&(!ui.createdFrom||r.date>=ui.createdFrom)&&(!ui.createdTo||r.date<=ui.createdTo)).sort((a,b)=>a.name.localeCompare(b.name,'he')*ui.sort);
 const pages=Math.max(1,Math.ceil(all.length/ui.size));ui.page=Math.min(ui.page,pages);const rows=all.slice((ui.page-1)*ui.size,ui.page*ui.size);
 const search=`<section class="record-search"><h2 class="underlined">חיפוש לקוח</h2><div class="search-grid"><label class="field"><span>שם לקוח</span><input id="record-query" data-field="query" value="${esc(ui.query)}" placeholder="שם לקוח או אימייל"></label><label class="field"><span>אימייל</span><input id="record-email" data-field="email" value="${esc(ui.email||'')}" placeholder="אימייל"></label><label class="field"><span>סטטוס לקוח</span><select data-field="status" id="record-status">${options(['',...statuses],ui.status)}</select></label><label class="field"><span>מנהל לקוח</span><select data-field="owner" id="record-owner">${options(['','צוות 1','צוות 2','צוות 3'],ui.owner)}</select></label><label class="field"><span>תאריך יצירה מ־</span><input type="date" id="created-from" data-field="createdFrom" value="${esc(ui.createdFrom||'')}"></label><label class="field"><span>תאריך יצירה עד</span><input type="date" id="created-to" data-field="createdTo" value="${esc(ui.createdTo||'')}"></label></div><div class="search-actions"><button data-action="search-records">חיפוש</button><button class="quiet" data-action="clear-search">ניקוי</button></div></section>`;
 if(ui.error)return search+'<div class="error"><h2>לא הצלחנו לטעון את הרשומות</h2><p>זוהי שגיאת הדגמה. הנתונים נשמרו.</p><button data-action="toggle-error">ניסיון נוסף</button></div>';
 return search+`<section class="record-results">${rows.length?`<div class="table-wrap"><table><thead><tr><th><button data-action="sort">שם ${ui.sort===1?'↑':'↓'}</button></th><th>אימייל</th><th>סטטוס לקוח</th><th>מנהל לקוח</th><th>תאריך יצירה</th><th>פעולות</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="row-link" data-action="edit-record" data-id="${r.id}">${esc(r.name)}</button></td><td dir="ltr">${esc(r.email)}</td><td>${esc(r.status)}</td><td>${esc(r.owner)}</td><td>${esc(r.date)}</td><td><button class="edit-icon" data-action="edit-record" data-id="${r.id}" aria-label="עריכת ${esc(r.name)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:empty()}<div class="pager"><label>רשומות בעמוד <select id="page-size" data-field="size">${options(['10','25','50','100'],String(ui.size))}</select></label><div class="actions"><button class="quiet small" data-action="previous" ${ui.page===1?'disabled':''} aria-label="הקודם">«</button><span>עמוד ${ui.page} מתוך ${pages}</span><button class="quiet small" data-action="next" ${ui.page===pages?'disabled':''} aria-label="הבא">»</button></div><span>מספר רשומות: <b>${all.length}</b></span></div></section><details class="test-states"><summary>מצבי הדגמה</summary><button class="outline small" data-action="toggle-error">הדמיית שגיאה</button></details>`;
}
